import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"Pull Requests","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"en/qgc-dev-guide/contribute/pull_requests.md","filePath":"en/qgc-dev-guide/contribute/pull_requests.md"}`),a={name:`en/qgc-dev-guide/contribute/pull_requests.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="pull-requests" tabindex="-1">Pull Requests <a class="header-anchor" href="#pull-requests" aria-label="Permalink to “Pull Requests”">​</a></h1><p>All pull requests go through the QGC CI build system (GitHub Actions), which:</p><ul><li>Builds QGC for each supported platform (Linux, Windows, macOS, Android and iOS), and in <a href="./../getting_started/container.html">containers</a>. Builds will fail if there are compiler warnings in QGC code.</li><li>Runs the <a href="./../contribute/unit_tests.html">unit tests</a> on Linux (with AddressSanitizer/UndefinedBehaviorSanitizer and with coverage instrumentation) and on a macOS Debug build.</li><li>Runs the pre-commit checks (<code>just lint</code>) on code changes, and the documentation lint (<code>just lint-docs</code>), link check and site build on documentation changes.</li></ul><p>Signing secrets are not available to pull request builds: Android builds are signed with a throwaway debug keystore and macOS builds are ad-hoc signed.</p><p>Follow <a href="https://www.conventionalcommits.org/" target="_blank" rel="noreferrer">Conventional Commits</a> for commit messages, and use the repository&#39;s pull request template to describe the change and how you tested it.</p><h2 id="automatic-release-note-generation" tabindex="-1">Automatic Release Note Generation <a class="header-anchor" href="#automatic-release-note-generation" aria-label="Permalink to “Automatic Release Note Generation”">​</a></h2><p>Release notes are generated from the following GitHub labels, which should be set on Pull Requests as appropriate:</p><ul><li>&quot;RN: MAJOR FEATURE&quot;</li><li>&quot;RN: MINOR FEATURE&quot;</li><li>&quot;RN: IMPROVEMENT&quot;</li><li>&quot;RN: REFACTORING&quot;</li><li>&quot;RN: BUGFIX&quot;</li><li>&quot;RN: NEW BOARD SUPPORT&quot;</li></ul><p>Variants of these labels ending in &quot;- CUSTOM BUILD&quot; indicate that the change is associated with the custom build architecture.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};